#!/usr/bin/env python3
"""dua - Disk Usage Analyzer"""

import os
import sys
import stat
import threading
import time
import argparse
import curses
import locale
import signal
import shutil
from collections import defaultdict

VERSION = "2.32.2"

# ANSI color codes
GREEN = "\033[32m"
CYAN = "\033[36m"
RESET = "\033[39m"
RESET_ALL = "\033[0m"

def format_size(size_bytes, fmt="binary"):
    """Format size in bytes according to the specified format."""
    if fmt == "bytes":
        return str(size_bytes), "b"
    elif fmt == "binary":
        units = ["B", "KiB", "MiB", "GiB", "TiB", "PiB"]
        v = float(size_bytes)
        u = 0
        while v > 1024 and u < len(units) - 1:
            v /= 1024
            u += 1
        if u == 0:
            return str(int(v)), "B"
        else:
            return f"{v:.2f}", units[u]
    elif fmt == "metric":
        units = ["B", "KB", "MB", "GB", "TB", "PB"]
        v = float(size_bytes)
        u = 0
        while v > 1000 and u < len(units) - 1:
            v /= 1000
            u += 1
        if u == 0:
            return str(int(v)), "B"
        else:
            return f"{v:.2f}", units[u]
    elif fmt == "gb":
        return f"{size_bytes / 1e9:.2f}", "GB"
    elif fmt == "gib":
        return f"{size_bytes / (1024**3):.2f}", "GiB"
    elif fmt == "mb":
        return f"{size_bytes / 1e6:.2f}", "MB"
    elif fmt == "mib":
        return f"{size_bytes / (1024**2):.2f}", "MiB"
    else:
        return str(size_bytes), "b"

def format_size_str(size_bytes, fmt="binary"):
    """Format size as a right-justified column string."""
    num, unit = format_size(size_bytes, fmt)
    if fmt == "binary":
        return f"{num:>7} {unit:>3}"  # 7+1+3 = 11
    elif fmt == "metric":
        return f"{num:>7} {unit:>2}"  # 7+1+2 = 10
    elif fmt == "bytes":
        return None  # handled specially (dynamic width)
    elif fmt == "gb":
        return f"{num:>7} {unit:>2}"  # 7+1+2 = 10
    elif fmt == "gib":
        return f"{num:>6} {unit:>3}"  # 6+1+3 = 10
    elif fmt == "mb":
        return f"{num:>9} {unit:>2}"  # 9+1+2 = 12
    elif fmt == "mib":
        return f"{num:>8} {unit:>3}"  # 8+1+3 = 12
    return f"{num} {unit}"

def get_file_size(path, apparent=False):
    """Get file size in bytes."""
    try:
        st = os.lstat(path)
        if apparent:
            return st.st_size
        else:
            return st.st_blocks * 512
    except (OSError, PermissionError):
        return 0

def get_path_size(path, apparent=False, count_hardlinks=False, stay_on_fs=False,
                  ignore_dirs=None, root_dev=None, seen_inodes=None):
    """Recursively compute size of a path."""
    if ignore_dirs is None:
        ignore_dirs = set()
    if seen_inodes is None:
        seen_inodes = set()

    try:
        st = os.lstat(path)
    except (OSError, PermissionError):
        return 0

    if stat.S_ISLNK(st.st_mode):
        # Don't follow symlinks (they're shown but not followed)
        if apparent:
            return st.st_size
        else:
            return st.st_blocks * 512

    if stay_on_fs and root_dev is not None and st.st_dev != root_dev:
        return 0

    if stat.S_ISDIR(st.st_mode):
        if os.path.abspath(path) in ignore_dirs:
            return 0

        total = 0
        try:
            entries = os.listdir(path)
        except (OSError, PermissionError):
            entries = []

        for entry in entries:
            child = os.path.join(path, entry)
            try:
                child_st = os.lstat(child)
            except (OSError, PermissionError):
                continue

            if stat.S_ISREG(child_st.st_mode):
                inode_key = (child_st.st_dev, child_st.st_ino)
                if not count_hardlinks and child_st.st_nlink > 1:
                    if inode_key in seen_inodes:
                        continue
                    seen_inodes.add(inode_key)
                if apparent:
                    total += child_st.st_size
                else:
                    total += child_st.st_blocks * 512
            elif stat.S_ISDIR(child_st.st_mode):
                child_path = os.path.realpath(child) if not stat.S_ISLNK(child_st.st_mode) else child
                total += get_path_size(child, apparent, count_hardlinks, stay_on_fs,
                                       ignore_dirs, root_dev or st.st_dev, seen_inodes)
            elif stat.S_ISLNK(child_st.st_mode):
                # Symlinks: show but don't follow
                if apparent:
                    total += child_st.st_size
                else:
                    total += child_st.st_blocks * 512

        return total
    else:
        # Regular file
        inode_key = (st.st_dev, st.st_ino)
        if not count_hardlinks and st.st_nlink > 1:
            if inode_key in seen_inodes:
                return 0
            seen_inodes.add(inode_key)
        if apparent:
            return st.st_size
        else:
            return st.st_blocks * 512

