            if not count_hardlinks and child_st.st_nlink > 1:
                if inode_key in seen_inodes:
                    size = 0
                else:
                    seen_inodes.add(inode_key)
                    if apparent:
                        size = child_st.st_size
                    else:
                        size = child_st.st_blocks * 512
            else:
                if apparent:
                    size = child_st.st_size
                else:
                    size = child_st.st_blocks * 512
        elif stat.S_ISDIR(child_st.st_mode):
            size = get_path_size(child, apparent, count_hardlinks, stay_on_fs,
                                 ignore_dirs, root_dev, seen_inodes.copy())
        elif stat.S_ISLNK(child_st.st_mode):
            if apparent:
                size = child_st.st_size
            else:
                size = child_st.st_blocks * 512
        else:
            size = 0

        result.append((entry, size))

    return result

def cmd_aggregate(args):
    """Aggregate subcommand."""
    fmt = args.format
    inputs = args.input

    # Determine default ignore dirs
    ignore_dirs = set(os.path.abspath(d) for d in args.ignore_dirs)

    if not inputs:
        # Use current directory
        inputs = ['.']

    if len(inputs) == 1:
        # Single input: if it's a directory, show its children
        path = inputs[0]
        try:
            st = os.lstat(path)
        except (OSError, PermissionError):
            print(f"dua: cannot access '{path}': No such file or directory", file=sys.stderr)
            return 1

        if stat.S_ISDIR(st.st_mode):
            # Show children
            entries = get_dir_entries(path,
                                      apparent=args.apparent_size,
                                      count_hardlinks=args.count_hard_links,
                                      stay_on_fs=args.stay_on_filesystem,
                                      ignore_dirs=ignore_dirs)

            if not args.no_sort:
                entries.sort(key=lambda x: x[1])

            total = sum(s for _, s in entries)

            # Format and print
            sizes = [s for _, s in entries]
            sizes.append(total)
            print_entries(entries, total, fmt, args.no_total, is_dir_children=True)

            if args.stats:
                sizes_only = [s for _, s in entries]
                smallest = min(sizes_only) if sizes_only else 0
                largest = max(sizes_only) if sizes_only else 0
                traversed = len(entries)
                print(f"Statistics {{ entries_traversed: {traversed}, smallest_file_in_bytes: {smallest}, largest_file_in_bytes: {largest} }}",
                      file=sys.stderr)
        else:
            # Single file
            if args.apparent_size:
                size = st.st_size
            else:
                size = st.st_blocks * 512
            entries = [(path, size)]
            print_entries(entries, size, fmt, args.no_total, is_dir_children=False, multiple=False)

            if args.stats:
                print(f"Statistics {{ entries_traversed: 1, smallest_file_in_bytes: {size}, largest_file_in_bytes: {size} }}",
                      file=sys.stderr)
    else:
        # Multiple inputs: show each with aggregate size
        entries = []
        seen_inodes = set()

        for path in inputs:
            try:
                st = os.lstat(path)
            except (OSError, PermissionError):
                entries.append((path, 0, False))
                continue

            if stat.S_ISDIR(st.st_mode):
                size = get_path_size(path,
                                     apparent=args.apparent_size,
                                     count_hardlinks=args.count_hard_links,
                                     stay_on_fs=args.stay_on_filesystem,
                                     ignore_dirs=ignore_dirs)
                entries.append((path, size, True))
            else:
                if args.apparent_size:
                    size = st.st_size
                else:
                    size = st.st_blocks * 512
                entries.append((path, size, False))

        if not args.no_sort:
            entries.sort(key=lambda x: x[1])

        total = sum(s for _, s, _ in entries)

        # Print
        all_sizes = [s for _, s, _ in entries]
        all_sizes.append(total)

        if fmt == "bytes":
            max_digits = max(len(str(s)) for s in all_sizes) if all_sizes else 1
            max_digits = max(max_digits, 1)

        for path, size, is_dir in entries:
            num, unit = format_size(size, fmt)
            if fmt == "bytes":
                size_str = f"{int(size):>{max_digits}} {unit}"
            else:
                size_str = format_size_str(size, fmt)

            if is_dir:
                # Add trailing slash, show in cyan
                display_path = path.rstrip('/') + '/'
                print(f"{GREEN}{size_str}{RESET} {CYAN}{display_path}{RESET}")
            else:
                print(f"{GREEN}{size_str}{RESET} {path}")

        if not args.no_total:
            num, unit = format_size(total, fmt)
            if fmt == "bytes":
                size_str = f"{int(total):>{max_digits}} {unit}"
            else:
                size_str = format_size_str(total, fmt)
            print(f"{GREEN}{size_str}{RESET} total")

        if args.stats:
            sizes_only = [s for _, s, _ in entries]
            smallest = min(sizes_only) if sizes_only else 0
            largest = max(sizes_only) if sizes_only else 0
            print(f"Statistics {{ entries_traversed: {len(entries)}, smallest_file_in_bytes: {smallest}, largest_file_in_bytes: {largest} }}",
                  file=sys.stderr)

def print_entries(entries, total, fmt, no_total, is_dir_children=True, multiple=True):
    """Print entries with proper formatting."""
    all_sizes = [s for _, s in entries]
    if multiple and not no_total:
        all_sizes.append(total)

    if fmt == "bytes":
        max_digits = max(len(str(s)) for s in all_sizes) if all_sizes else 1
        max_digits = max(max_digits, 1)

    for name, size in entries:
        num, unit = format_size(size, fmt)
        if fmt == "bytes":
            size_str = f"{int(size):>{max_digits}} {unit}"
        else:
            size_str = format_size_str(size, fmt)
        print(f"{GREEN}{size_str}{RESET} {name}")

    if not no_total and multiple:
        num, unit = format_size(total, fmt)
        if fmt == "bytes":
            size_str = f"{int(total):>{max_digits}} {unit}"
        else:
            size_str = format_size_str(total, fmt)
        print(f"{GREEN}{size_str}{RESET} total")

