#!/usr/bin/env python3
"""dua - Disk Usage Analyzer v2.32.2"""

import os
import sys
import stat
import time
import threading
import argparse
import curses
import locale
import signal
import fnmatch
import datetime
from collections import defaultdict

VERSION = "2.32.2"

# ANSI color codes for aggregate output
GREEN = "\033[32m"
CYAN = "\033[36m"
RESET_FG = "\033[39m"
RESET_ALL = "\033[0m"

# ============================================================
# Size formatting
# ============================================================

def format_size(size_bytes, fmt="binary"):
    """Return (number_str, unit_str) for size_bytes."""
    if fmt == "bytes":
        return str(int(size_bytes)), "b"
    elif fmt == "binary":
        units = ["B", "KiB", "MiB", "GiB", "TiB", "PiB"]
        v = float(size_bytes)
        u = 0
        while v > 1024 and u < len(units) - 1:
            v /= 1024
            u += 1
        if u == 0:
            return str(int(v)), "B"
        return f"{v:.2f}", units[u]
    elif fmt == "metric":
        units = ["B", "KB", "MB", "GB", "TB", "PB"]
        v = float(size_bytes)
        u = 0
        while v > 1000 and u < len(units) - 1:
            v /= 1000
            u += 1
        if u == 0:
            return str(int(v)), "B"
        return f"{v:.2f}", units[u]
    elif fmt == "gb":
        return f"{size_bytes / 1e9:.2f}", "GB"
    elif fmt == "gib":
        return f"{size_bytes / (1024**3):.2f}", "GiB"
    elif fmt == "mb":
        return f"{size_bytes / 1e6:.2f}", "MB"
    elif fmt == "mib":
        return f"{size_bytes / (1024**2):.2f}", "MiB"
    return str(int(size_bytes)), "b"

def format_size_col(size_bytes, fmt="binary"):
    """Format size as fixed-width column string."""
    num, unit = format_size(size_bytes, fmt)
    if fmt == "binary":
        return f"{num:>7} {unit:>3}"   # 11 chars
    elif fmt == "metric":
        return f"{num:>7} {unit:>2}"   # 10 chars
    elif fmt == "bytes":
        return None  # handled specially
    elif fmt == "gb":
        return f"{num:>7} {unit:>2}"   # 10 chars
    elif fmt == "gib":
        return f"{num:>6} {unit:>3}"   # 10 chars
    elif fmt == "mb":
        return f"{num:>9} {unit:>2}"   # 12 chars
    elif fmt == "mib":
        return f"{num:>8} {unit:>3}"   # 12 chars
    return f"{num} {unit}"

# ============================================================
# File system traversal
# ============================================================

def get_stat(path):
    try:
        return os.lstat(path)
    except OSError:
        return None

def path_disk_size(st, apparent):
    if apparent:
        return st.st_size
    return st.st_blocks * 512

def scan_dir(path, apparent=False, count_hardlinks=False, stay_on_fs=False,
             ignore_dirs=None, root_dev=None, seen_inodes=None):
    """Recursively compute disk usage of path."""
    if ignore_dirs is None:
        ignore_dirs = set()
    if seen_inodes is None:
        seen_inodes = {}

    st = get_stat(path)
    if st is None:
        return 0

    if stat.S_ISLNK(st.st_mode):
        return path_disk_size(st, apparent)

    if not stat.S_ISDIR(st.st_mode):
        # Regular file or other
        if stat.S_ISREG(st.st_mode):
            key = (st.st_dev, st.st_ino)
            if not count_hardlinks and st.st_nlink > 1:
                if key in seen_inodes:
                    return 0
                seen_inodes[key] = True
        return path_disk_size(st, apparent)

    # Directory
    abs_path = os.path.abspath(path)
    if abs_path in ignore_dirs:
        return 0

    if root_dev is None:
        root_dev = st.st_dev

    if stay_on_fs and st.st_dev != root_dev:
        return 0

    total = 0
    try:
        entries = os.scandir(path)
    except OSError:
        return 0

    with entries:
        for entry in entries:
            try:
                child_st = entry.stat(follow_symlinks=False)
            except OSError:
                continue

            if stat.S_ISLNK(child_st.st_mode):
                total += path_disk_size(child_st, apparent)
            elif stat.S_ISREG(child_st.st_mode):
                key = (child_st.st_dev, child_st.st_ino)
                if not count_hardlinks and child_st.st_nlink > 1:
                    if key in seen_inodes:
                        continue
                    seen_inodes[key] = True
                total += path_disk_size(child_st, apparent)
            elif stat.S_ISDIR(child_st.st_mode):
                child_abs = os.path.abspath(entry.path)
                if child_abs in ignore_dirs:
                    continue
                if stay_on_fs and child_st.st_dev != root_dev:
                    continue
                total += scan_dir(entry.path, apparent, count_hardlinks, stay_on_fs,
                                   ignore_dirs, root_dev, seen_inodes)
            else:
                total += path_disk_size(child_st, apparent)

    return total

def get_dir_children(path, apparent=False, count_hardlinks=False, stay_on_fs=False,
                     ignore_dirs=None):
    """Get direct children of path with their sizes."""
    if ignore_dirs is None:
        ignore_dirs = set()

    st = get_stat(path)
    if st is None:
        return []
    root_dev = st.st_dev

    results = []
    seen_inodes = {}

    try:
        entries = list(os.scandir(path))
    except OSError:
        return []

    for entry in entries:
        try:
            child_st = entry.stat(follow_symlinks=False)
        except OSError:
            results.append((entry.name, 0, child_st if False else None))
            continue

        if stat.S_ISLNK(child_st.st_mode):
            size = path_disk_size(child_st, apparent)
            results.append((entry.name, size, child_st))
        elif stat.S_ISREG(child_st.st_mode):
            key = (child_st.st_dev, child_st.st_ino)
            if not count_hardlinks and child_st.st_nlink > 1:
                if key in seen_inodes:
                    size = 0
                else:
                    seen_inodes[key] = True
                    size = path_disk_size(child_st, apparent)
            else:
                size = path_disk_size(child_st, apparent)
            results.append((entry.name, size, child_st))
        elif stat.S_ISDIR(child_st.st_mode):
            child_abs = os.path.abspath(entry.path)
            if child_abs in ignore_dirs:
                size = 0
            elif stay_on_fs and child_st.st_dev != root_dev:
                size = 0
            else:
                size = scan_dir(entry.path, apparent, count_hardlinks, stay_on_fs,
                                ignore_dirs, root_dev, {})
            results.append((entry.name, size, child_st))
        else:
            size = path_disk_size(child_st, apparent)
            results.append((entry.name, size, child_st))

    return results

# ============================================================
# Aggregate command
# ============================================================

def cmd_aggregate(args):
    fmt = args.format
    inputs = list(args.input) if args.input else []
    ignore_dirs = set(os.path.abspath(d) for d in (args.ignore_dirs or []))

    if not inputs:
        # Use all entries in current working directory
        inputs = ['.']
        single_dir_mode = True
    else:
        single_dir_mode = (len(inputs) == 1)

    if single_dir_mode:
        path = inputs[0]
        st = get_stat(path)
        if st is None:
            print(f"dua: cannot access '{path}': No such file or directory", file=sys.stderr)
            return 1

        if stat.S_ISDIR(st.st_mode):
            children = get_dir_children(path,
                                         apparent=args.apparent_size,
                                         count_hardlinks=args.count_hard_links,
                                         stay_on_fs=args.stay_on_filesystem,
                                         ignore_dirs=ignore_dirs)

            entries_with_stat = [(name, size, cst) for name, size, cst in children]

            if not args.no_sort:
                entries_with_stat.sort(key=lambda x: x[1])

            total = sum(s for _, s, _ in entries_with_stat)

            # For bytes format, need max width
            all_sizes = [s for _, s, _ in entries_with_stat]
            if not args.no_total:
                all_sizes.append(total)

            if fmt == "bytes":
                if all_sizes:
                    max_w = max(len(str(s)) for s in all_sizes)
                    max_w = max(max_w, 1)
                else:
                    max_w = 1

            for name, size, cst in entries_with_stat:
                if fmt == "bytes":
                    num, unit = format_size(size, fmt)
                    size_str = f"{int(size):>{max_w}} {unit}"
                else:
                    size_str = format_size_col(size, fmt)
                print(f"{GREEN}{size_str}{RESET_FG} {name}")

            if not args.no_total:
                if fmt == "bytes":
                    size_str = f"{int(total):>{max_w}} {unit}"
                else:
                    size_str = format_size_col(total, fmt)
                print(f"{GREEN}{size_str}{RESET_FG} total")

            if hasattr(args, 'stats') and args.stats:
                sizes_only = [s for _, s, _ in entries_with_stat]
                smallest = min(sizes_only) if sizes_only else 0
                largest = max(sizes_only) if sizes_only else 0
                print(f"Statistics {{ entries_traversed: {len(entries_with_stat)}, "
                      f"smallest_file_in_bytes: {smallest}, "
                      f"largest_file_in_bytes: {largest} }}", file=sys.stderr)
        else:
            # Single file
            if args.apparent_size:
                size = st.st_size
            else:
                size = st.st_blocks * 512

            if fmt == "bytes":
                max_w = max(len(str(size)), 1)
                num, unit = format_size(size, fmt)
                size_str = f"{int(size):>{max_w}} {unit}"
            else:
