# ============================================================
# Bar rendering
# ============================================================

BLOCK_CHARS = " ▏▎▍▌▋▊▉█"  # index 0=empty, 1-7=partial, 8=full

def make_bar(pct, bar_visual_width=10, total_chars=11):
    """Make a bar string. bar_visual_width columns, total_chars string length."""
    filled = pct / 100.0 * bar_visual_width
    full_blocks = int(filled)
    frac = filled - full_blocks
    frac_idx = round(frac * 8)
    if frac_idx >= 8:
        full_blocks += 1
        frac_idx = 0
    if frac_idx > 0 and full_blocks < bar_visual_width:
        partial = chr(0x2590 - frac_idx)  # ▏=1..▉=7
        s = '█' * full_blocks + partial
    else:
        s = '█' * full_blocks
    # Pad to total_chars
    if len(s) < total_chars:
        s = s + ' ' * (total_chars - len(s))
    return s

def format_bar_section(pct, mode):
    """
    mode 0: percentage + bar  (21 chars: pct(8) + '  ' + bar(11))
    mode 1: percentage only   (10 chars: pct(8) + '  ')
    mode 2: small bar only    (12 chars: ' ' + bar(11))
    mode 3: big bar only      (21 chars: ' ' + big_bar(20))
    """
    if mode == 0:
        pct_str = f"{pct:7.1f}%"  # 8 chars
        bar = make_bar(pct, 10, 11)
        return pct_str + "  " + bar  # 8+2+11=21
    elif mode == 1:
        pct_str = f"{pct:7.1f}%"  # 8 chars
        return pct_str + "  "  # 8+2=10
    elif mode == 2:
        bar = make_bar(pct, 10, 11)
        return " " + bar  # 1+11=12
    elif mode == 3:
        bar = make_bar(pct, 19, 20)
        return " " + bar  # 1+20=21
    return ""

# ============================================================
# Interactive TUI
# ============================================================

# Colors for curses
COLOR_GREEN = 1
COLOR_CYAN = 2
COLOR_SELECTED = 3
COLOR_TITLE_BG = 4
COLOR_MARKED = 5
COLOR_GRAY = 6
COLOR_BOLD = 7

# Sort modes
SORT_SIZE_DESC = 0
SORT_SIZE_ASC = 1
SORT_MTIME_DESC = 2
SORT_MTIME_ASC = 3
SORT_COUNT_DESC = 4
SORT_COUNT_ASC = 5
SORT_NAME_ASC = 6
SORT_NAME_DESC = 7

SORT_NAMES = {
    SORT_SIZE_DESC: "size descending",
    SORT_SIZE_ASC: "size ascending",
    SORT_MTIME_DESC: "modified descending",
    SORT_MTIME_ASC: "modified ascending",
    SORT_COUNT_DESC: "items descending",
    SORT_COUNT_ASC: "items ascending",
    SORT_NAME_ASC: "name ascending",
    SORT_NAME_DESC: "name descending",
}

class Entry:
    """Represents a file system entry in the interactive view."""
    def __init__(self, name, path, size, is_dir, mtime=0, item_count=0):
        self.name = name
        self.path = path
        self.size = size
        self.is_dir = is_dir
        self.mtime = mtime
        self.item_count = item_count
        self.marked = False

class DirState:
    """State for a directory being viewed."""
    def __init__(self, path, entries, total_size, total_items, scan_time=0.0):
        self.path = path
        self.entries = entries  # list of Entry
        self.total_size = total_size
        self.total_items = total_items
        self.scan_time = scan_time
        self.scroll = 0
        self.selected = 0
        self.sort_mode = SORT_SIZE_DESC
        self.filter_glob = None
        self.show_mtime = False
        self.show_count = False
        self.bar_mode = 0  # 0=pct+bar, 1=pct, 2=small_bar, 3=big_bar

def count_items(path):
    """Count total items in directory tree."""
    count = 0
    try:
        for entry in os.scandir(path):
            count += 1
            if entry.is_dir(follow_symlinks=False):
                count += count_items(entry.path)
    except OSError:
        pass
    return count

def scan_directory(path, apparent=False, count_hardlinks=False,
                   stay_on_fs=False, ignore_dirs=None, fmt="binary"):
    """Scan a directory and return DirState."""
    if ignore_dirs is None:
        ignore_dirs = set()

    t0 = time.time()
    st = get_stat(path)
    if st is None:
        return DirState(path, [], 0, 0, 0)

    root_dev = st.st_dev

    try:
        raw_entries = list(os.scandir(path))
    except OSError:
        return DirState(path, [], 0, 0, 0)

    entries = []
    seen_inodes = {}
    total_size = 0
    total_items = len(raw_entries)

    for e in raw_entries:
        try:
            child_st = e.stat(follow_symlinks=False)
        except OSError:
            entries.append(Entry(e.name, e.path, 0, False))
            continue

        mtime = child_st.st_mtime if hasattr(child_st, 'st_mtime') else 0

        if stat.S_ISLNK(child_st.st_mode):
            size = path_disk_size(child_st, apparent)
            entries.append(Entry(e.name, e.path, size, False, mtime))
            total_size += size
        elif stat.S_ISREG(child_st.st_mode):
            key = (child_st.st_dev, child_st.st_ino)
            if not count_hardlinks and child_st.st_nlink > 1:
                if key in seen_inodes:
                    size = 0
                else:
                    seen_inodes[key] = True
                    size = path_disk_size(child_st, apparent)
            else:
                size = path_disk_size(child_st, apparent)
            entries.append(Entry(e.name, e.path, size, False, mtime))
            total_size += size
        elif stat.S_ISDIR(child_st.st_mode):
            child_abs = os.path.abspath(e.path)
            if child_abs in ignore_dirs:
                size = 0
            elif stay_on_fs and child_st.st_dev != root_dev:
                size = 0
            else:
                size = scan_dir(e.path, apparent, count_hardlinks, stay_on_fs,
                                ignore_dirs, root_dev, {})
            item_count = 0  # would need extra scan
            entries.append(Entry(e.name, e.path, size, True, mtime, item_count))
            total_size += size
        else:
            size = path_disk_size(child_st, apparent)
            entries.append(Entry(e.name, e.path, size, False, mtime))
            total_size += size

    scan_time = time.time() - t0
    return DirState(path, entries, total_size, total_items, scan_time)

def sort_entries(entries, sort_mode):
    """Sort entries by sort_mode."""
    if sort_mode == SORT_SIZE_DESC:
        return sorted(entries, key=lambda e: e.size, reverse=True)
    elif sort_mode == SORT_SIZE_ASC:
        return sorted(entries, key=lambda e: e.size)
    elif sort_mode == SORT_MTIME_DESC:
        return sorted(entries, key=lambda e: e.mtime, reverse=True)
    elif sort_mode == SORT_MTIME_ASC:
        return sorted(entries, key=lambda e: e.mtime)
    elif sort_mode == SORT_COUNT_DESC:
        return sorted(entries, key=lambda e: e.item_count, reverse=True)
    elif sort_mode == SORT_COUNT_ASC:
        return sorted(entries, key=lambda e: e.item_count)
    elif sort_mode == SORT_NAME_ASC:
        return sorted(entries, key=lambda e: e.name.lower())
    elif sort_mode == SORT_NAME_DESC:
        return sorted(entries, key=lambda e: e.name.lower(), reverse=True)
    return entries

def filter_entries(entries, glob_pattern):
    """Filter entries by glob pattern (case-insensitive)."""
    if not glob_pattern:
        return entries
    pat = glob_pattern.lower()
    return [e for e in entries if fnmatch.fnmatch(e.name.lower(), pat)]

def get_visible_entries(state):
    """Get sorted and filtered entries."""
    entries = sort_entries(state.entries, state.sort_mode)
    if state.filter_glob:
        entries = filter_entries(entries, state.filter_glob)
    return entries

