TOP_SHORTCUTS = ". = o|.. = u \u2500\u2500 \u21ca = Ctrl+d|\u2193 = j|\u21c8 = Ctrl+u|\u2191 = k"
BOTTOM_SHORTCUTS = "mark-move = d | mark-toggle = space | toggle-all = a"

def draw_hline(stdscr, y, x, width, ch='\u2500'):
    """Draw a horizontal line."""
    try:
        stdscr.addstr(y, x, ch * width)
    except curses.error:
        pass

def safe_addstr(stdscr, y, x, s, attr=0, max_width=None):
    """Add string safely, truncating if needed."""
    if y < 0:
        return
    try:
        h, w = stdscr.getmaxyx()
        if y >= h or x >= w:
            return
        if max_width is not None:
            available = min(max_width, w - x)
        else:
            available = w - x
        if available <= 0:
            return
        # Truncate string to fit
        truncated = s[:available]
        if attr:
            stdscr.addstr(y, x, truncated, attr)
        else:
